<script setup lang="ts">
import { Search,ArrowRight } from '@element-plus/icons-vue'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import type {DeviceType} from './api'
import {activitySupported,type DirectoryActivity} from './directory-activity-capabilities'
export type CatalogView='cards'|'table'|'map'
/** 原站表单状态；接入适配器负责转换为唯一生成的网络合同。 */
export type CatalogFilterForm={online:string;activity:string;alarm:string;enabled:string;kind:string}
const props=defineProps<{types:DeviceType[];typeId:string;keyword:string;order:string;view:CatalogView;filters:CatalogFilterForm;hasMoreTypes?:boolean;loadingTypes?:boolean;groupsVisible?:boolean;disabled?:boolean;activity?:DirectoryActivity;policyAvailable?:boolean}>()
const emit=defineEmits<{'update:typeId':[string];'update:keyword':[string];'update:order':[string];'update:view':[CatalogView];'update:filters':[CatalogFilterForm];search:[];groups:[];queries:[];moreTypes:[];'activity-policy':[]}>()
const filterRows:Array<{key:keyof CatalogFilterForm;label:string;options:Array<[string,string]>}>=[
 {key:'online',label:'在线状态',options:[['','不限'],['ONLINE','在线'],['OFFLINE','离线']]},
 {key:'activity',label:'活跃状态',options:[['','不限'],['ACTIVE','活跃'],['SEEN_5_MINUTES','5分钟内活跃'],['SEEN_1_HOUR','1小时内活跃'],['SEEN_1_DAY','1天内活跃'],['INACTIVE','不活跃'],['NOT_SEEN_1_DAY','不活跃超过1天'],['NOT_SEEN_3_DAYS','不活跃超过3天'],['NOT_SEEN_7_DAYS','不活跃超过7天'],['NEVER','从未活跃']]},
 {key:'alarm',label:'告警状态',options:[['','不限'],['NORMAL','未告警'],['ACTIVE','告警中'],['MINOR','普通告警'],['MAJOR','重要告警'],['CRITICAL','紧急告警']]},
 {key:'enabled',label:'设备状态',options:[['','不限'],['true','正常'],['false','已停用']]},
 {key:'kind',label:'接入类型',options:[['','不限'],['DIRECT','直连设备'],['SUB_DEVICE','网关子设备'],['GATEWAY','网关']]},
]
function unsupported(key:keyof CatalogFilterForm,value:string){return key==='activity'&&(value==='ACTIVE'||value==='INACTIVE')&&!activitySupported(props.activity,value)}
function selectFilter(key:keyof CatalogFilterForm,value:string){if(props.disabled||unsupported(key,value))return;emit('update:filters',{...props.filters,[key]:value});emit('search')}
</script>
<template><div class="tl-toolbar catalog-toolbar"><el-button :disabled="disabled" size="small" :type="groupsVisible?'primary':'default'" :plain="groupsVisible" @click="emit('groups')"><ReferenceIcon glyph="󰙅"/>设备组</el-button><el-button size="small" :disabled="disabled" @click="emit('queries')"><ReferenceIcon glyph="󱘶"/>设备查询</el-button><el-select :disabled="disabled" :model-value="typeId" size="small" clearable filterable placeholder="不限设备类型" aria-label="设备类型筛选" style="width:125px" @update:model-value="emit('update:typeId',$event);emit('search')"><el-option v-for="type in types" :key="type.id" :value="type.id!" :label="type.name"/><template v-if="hasMoreTypes" #footer><el-button :disabled="disabled" text :loading="loadingTypes" @click="emit('moreTypes')">加载更多</el-button></template></el-select><el-button v-if="typeId" size="small" :disabled="disabled||!policyAvailable" :title="!typeId?'请先选择设备类型':!policyAvailable?'当前类型策略读取能力不可用':undefined" @click="!disabled&&policyAvailable&&emit('activity-policy')">类型活跃设置</el-button><el-popover :disabled="disabled" placement="bottom-start" trigger="click" :width="700" popper-class="device-reference-filters"><template #reference><el-button :disabled="disabled" size="small">更多筛选<el-icon class="filter-arrow"><ArrowRight/></el-icon></el-button></template><div v-for="row in filterRows" :key="row.key" class="filter-row"><span class="filter-label">{{row.label}}</span><div class="filter-values"><button v-for="[value,label] in row.options" :key="value" type="button" :class="{selected:filters[row.key]===value}" :aria-pressed="filters[row.key]===value" :disabled="disabled||unsupported(row.key,value)" :title="unsupported(row.key,value)?value==='INACTIVE'?'当前未开放完整窗口的不活跃筛选':'当前未开放合格通信正证据筛选':undefined" @click="selectFilter(row.key,value)">{{label}}</button></div></div></el-popover><el-input :disabled="disabled" :model-value="keyword" size="small" clearable placeholder="搜索设备" aria-label="搜索设备" :prefix-icon="Search" style="width:180px" @update:model-value="emit('update:keyword',$event)" @keyup.enter="emit('search')" @clear="emit('search')"/><slot name="selection"/><div class="tl-toolbar__end"><el-select :disabled="disabled" :model-value="order" size="small" class="catalog-order" aria-label="设备排序" style="width:100px" @update:model-value="emit('update:order',$event);emit('search')"><el-option value="CREATED_ASC" label="最早创建"/><el-option value="CREATED_DESC" label="最新创建"/><el-option value="ACTIVE_DESC" label="最近活跃"/><el-option value="NAME_ASC" label="设备名称"/></el-select><el-button-group><el-button :disabled="disabled" size="small" :type="view==='cards'?'primary':'default'" aria-label="卡片视图" @click="emit('update:view','cards')"><ReferenceIcon glyph="󱇙"/></el-button><el-button :disabled="disabled" size="small" :type="view==='table'?'primary':'default'" aria-label="表格视图" @click="emit('update:view','table')"><ReferenceIcon glyph="󰕱"/></el-button><el-button size="small" :type="view==='map'?'primary':'default'" aria-label="地图视图" :disabled="disabled" title="查看当前页人工位置" @click="emit('update:view','map')"><ReferenceIcon glyph="󱋼"/></el-button></el-button-group></div></div></template>
<style scoped>.catalog-toolbar{gap:8px;min-height:33px;}.catalog-toolbar :deep(.reference-icon){font-size:13px;margin-right:4px;}.catalog-toolbar :deep(.el-button-group .reference-icon){font-size:12px;margin:0;}.catalog-toolbar :deep(.el-button){height:33px;}.catalog-toolbar>.el-button{font-size:13px;}.catalog-toolbar :deep(.el-select__wrapper){min-height:33px;height:33px;}.catalog-order :deep(.el-select__selected-item){text-align:center;}.catalog-toolbar :deep(.el-input){--el-input-height:33px;}.catalog-toolbar>.el-button+.el-button{margin-left:0;}.filter-arrow{margin-left:7px;color:var(--tl-muted);}.filter-row{display:flex;align-items:flex-start;font-size:12px;line-height:24px;margin:5px 0;}.filter-label{width:86px;flex:none;color:var(--tl-title);padding:2px 0;}.filter-values{display:flex;flex-wrap:wrap;gap:2px 4px;}.filter-values button:not(.el-button){font:inherit;font-size:12px;border:0;background:none;color:var(--tl-text);padding:2px 6px;cursor:pointer;white-space:nowrap;}.filter-values button:not(.el-button):disabled{color:var(--tl-muted);cursor:not-allowed;opacity:.55;}.filter-values button:not(.el-button):hover,.filter-values button:not(.el-button).selected{color:var(--tl-primary);}@media(max-width:1100px){.tl-toolbar__end{margin-left:0;}}</style>
